mapper.select:
SELECT e.id
FROM expert_major em
INNER JOIN expert_info e ON e.id = em.expert_id
WHERE e.del_flag = '0'
AND e.status = '0'
AND em.major_code = #{majorCode}
AND e.region_code = #{regionCode}
AND NOT EXISTS (
SELECT 1 FROM expert_extract_result r
WHERE r.expert_id = e.id
AND r.evaluate_date = #{evaluateDate}
AND r.status IN ('WAIT_CONFIRM', 'JOIN')
)
AND NOT EXISTS (
SELECT 1 FROM expert_extract_avoid a
WHERE a.extract_id = #{extractId}
AND a.avoid_type = 'EXPERT'
AND a.expert_name = e.expert_name
AND a.id_card = e.id_card
)
AND NOT EXISTS (
SELECT 1 FROM expert_extract_avoid a
WHERE a.extract_id = #{extractId}
AND a.avoid_type = 'COMPANY'
AND a.company_name = e.company_name
)

    AND e.id NOT IN

        #{excludeId}

SELECT em.major_code AS major_code,
       COUNT(DISTINCT e.id) AS available_num
FROM expert_major em
INNER JOIN expert_info e ON e.id = em.expert_id
WHERE e.del_flag = '0'
AND e.status = '0'
AND e.region_code = #{regionCode}
AND NOT EXISTS (
SELECT 1 FROM expert_extract_result r
WHERE r.expert_id = e.id
AND r.evaluate_date = #{evaluateDate}
AND r.status IN ('WAIT_CONFIRM', 'JOIN')
)

    AND CONCAT(e.expert_name, '|', e.id_card) NOT IN

        #{expertKey}



    AND (e.company_name IS NULL OR e.company_name NOT IN

        #{company}

    )

GROUP BY em.major_code
